const publishers = [
  [/^https:\/\/learn\.microsoft\.com\//, 'Microsoft Learn'],
  [/^https:\/\/devblogs\.microsoft\.com\//, 'Microsoft Developer Blogs'],
  [/^https:\/\/(www\.)?postgresql\.org\//, 'PostgreSQL Global Development Group'],
  [/^https:\/\/docs\.citusdata\.com\//, 'Citus Data'],
  [/^https:\/\/(dev\.mysql\.com|docs\.oracle\.com)\//, 'Oracle (MySQL Reference Manual)'],
  [/^https:\/\/(www\.)?mongodb\.com\//, 'MongoDB'],
  [/^https:\/\/cassandra\.apache\.org\//, 'Apache Software Foundation'],
  [/^https:\/\/redis\.io\//, 'Redis'],
  [/^https:\/\/mariadb\.com\//, 'MariaDB']
];

function publisherFor(url) {
  const match = publishers.find(([pattern]) => pattern.test(url));
  if (!match) throw new Error(`No publisher mapping for ${url}`);
  return match[1];
}

